class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> List[List[int]]:
        out=[];path=[]
        def dfs(node,remain):
            if not node:return
            path.append(node.val);remain-=node.val
            if not node.left and not node.right and remain==0:out.append(path.copy())
            else:dfs(node.left,remain);dfs(node.right,remain)
            path.pop()
        dfs(root,targetSum);return out

