class Solution {
    public List<List<Integer>> pathSum(TreeNode root,int targetSum){List<List<Integer>>out=new ArrayList<>();dfs(root,targetSum,new ArrayList<>(),out);return out;}
    private void dfs(TreeNode n,int rem,List<Integer>p,List<List<Integer>>out){if(n==null)return;p.add(n.val);rem-=n.val;if(n.left==null&&n.right==null&&rem==0)out.add(new ArrayList<>(p));else{dfs(n.left,rem,p,out);dfs(n.right,rem,p,out);}p.remove(p.size()-1);}
}

