class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        dp=[0]*(len(t)+1);dp[0]=1
        for ch in s:
            for j in range(len(t),0,-1):
                if ch==t[j-1]:dp[j]+=dp[j-1]
        return dp[-1]

class Solution {
    public int numDistinct(String s,String t){int[]dp=new int[t.length()+1];dp[0]=1;for(int i=0;i<s.length();i++)for(int j=t.length();j>=1;j--)if(s.charAt(i)==t.charAt(j-1))dp[j]+=dp[j-1];return dp[t.length()];}
}

